import React, { useEffect, useState } from "react";
import API_BASE_URL from "../config";
import "../styles/AdminPages.css";

const MessageCenter = ({ receiverId }) => {
  const senderId = sessionStorage.getItem("userId");
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  const fetchMessages = async () => {
    const res = await fetch(`${API_BASE_URL}/api/messages/${senderId}/${receiverId}`);
    const data = await res.json();
    setMessages(data);
  };

  const sendMessage = async () => {
    await fetch(`${API_BASE_URL}/api/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ sender_id: senderId, receiver_id: receiverId, message: text }),
    });
    setText("");
    fetchMessages();
  };

  useEffect(() => {
    fetchMessages();
  }, []);

  return (
    <div className="message-center">
      <div className="messages">
        {messages.map((msg) => (
          <div key={msg.id} className={msg.sender_id == senderId ? "sent" : "received"}>
            <p>{msg.message}</p>
            <span>{new Date(msg.timestamp).toLocaleString()}</span>
          </div>
        ))}
      </div>
      <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Type a message..." />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
};

export default MessageCenter;
